CREATE TABLE bills(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,session_id BINARY(16) NOT NULL UNIQUE,tariff_id BINARY(16),bill_number VARCHAR(50) NOT NULL UNIQUE,energy_kwh DECIMAL(12,3) NOT NULL,duration_minutes BIGINT NOT NULL,energy_amount DECIMAL(12,2) NOT NULL,time_amount DECIMAL(12,2) NOT NULL,session_fee DECIMAL(12,2) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,tax_percent DECIMAL(5,2) NOT NULL,tax_amount DECIMAL(12,2) NOT NULL,total_amount DECIMAL(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,paid_at TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_bills_tenant_created ON bills(tenant_id,created_at);CREATE INDEX idx_bills_user ON bills(user_id);
